describe('HTTP Status Code Reporting', () => {
  beforeEach(() => {
    cy.visit('/status_codes');
  });

  it('should navigate to specific status code page and verify response text', () => {
    // Click the link for status code 200
    cy.get('[data-testid="status-code-200-link"]').click();

    // Wait for navigation
    cy.intercept('GET', '/status_codes/200').as('statusCode200');
    cy.wait('@statusCode200');

    // Verify URL contains status code
    cy.url().should('include', '/status_codes/200');

    // Verify page body contains expected text
    cy.get('[data-testid="page-body"]').should('contain', 'This page returned a 200 status code');

    // Return to /status_codes
    cy.visit('/status_codes');
  });

  it('should handle 404 status code and verify error message', () => {
    // Click the link for status code 404
    cy.get('[data-testid="status-code-404-link"]').click();

    // Wait for navigation
    cy.intercept('GET', '/status_codes/404').as('statusCode404');
    cy.wait('@statusCode404');

    // Verify URL contains status code
    cy.url().should('include', '/status_codes/404');

    // Verify page body contains expected error message
    cy.get('[data-testid="page-body"]').should('contain', 'This page returned a 404 status code');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Return to /status_codes
    cy.visit('/status_codes');
  });
});
